"use client";

import { useEffect, useState } from "react";

import ClearIcon from '@mui/icons-material/Clear';
import SyncAltIcon from '@mui/icons-material/SyncAlt';

import Header from "../components/Header.js";
import { criarCliente, listarClientes, removerCliente } from "../lib/api.js";
import ModalClienteUpdate from "./components/ModalClienteUpdate.js";


export default function CadastroClientePage() {
  const [clientes, setClientes] = useState([]);
  const [openModal, setOpenModal] = useState(false);
  const [dadosCliente, setDadosCliente] = useState(null);

  useEffect(() => {
    async function carregar() {
      const dados = await listarClientes();
      if (dados) setClientes(dados);
    }
    carregar();
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const formData = new FormData(e.target);
    const dados = Object.fromEntries(formData.entries());

    await criarCliente(dados);

    const atualizada = await listarClientes();
    setClientes(atualizada);

    e.target.reset();
  }

  async function handleRemoveCliente(id) {
    try {
      await removerCliente(id);
      const atualizada = await listarClientes();
      setClientes(atualizada);
    } catch (err) {
      console.error(err);
    }
  }


  return (
    <>
      <Header />

      <div className="flex flex-row gap-8 w-full min-h-screen items-start justify-center bg-[#fff7e6] p-10">
        <div className="w-full max-w-md bg-white shadow-lg rounded-xl border border-orange-200 p-8">
          <h1 className="text-2xl text-gray-700 font-semibold text-center mb-6">
            Cadastro de Cliente
          </h1>

          <form onSubmit={handleSubmit} className="space-y-4">

            {/* Nome */}
            <div>
              <p htmlFor="nome" className="block text-sm font-medium text-gray-700 mb-1">
                Nome completo
              </p>
              <input
                id="nome"
                name="nome"
                type="text"
                required
                className="text-black block w-full rounded-md border border-gray-300 px-3 py-2 text-sm shadow-sm
                focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-orange-400"
                placeholder="Ex.: João da Silva"
              />
            </div>

            {/* Documento */}
            <div>
              <p htmlFor="cpf" className="block text-sm font-medium text-gray-700 mb-1">
                Documento (CPF ou RG)
              </p>
              <input
                id="cpf"
                name="cpf"
                type="text"
                required
                className="text-black block w-full rounded-md border border-gray-300 px-3 py-2 text-sm shadow-sm
                focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-orange-400"
                placeholder="Ex.: 123.456.789-00"
              />
            </div>

            {/* Telefone */}
            <div>
              <p htmlFor="telefone" className="block text-sm font-medium text-gray-700 mb-1">
                Telefone
              </p>
              <input
                id="telefone"
                name="telefone"
                type="text"
                className="text-black block w-full rounded-md border border-gray-300 px-3 py-2 text-sm shadow-sm
                focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-orange-400"
                placeholder="Ex.: (41) 99999-9999"
              />
            </div>

            {/* Email */}
            <div>
              <p htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
                E-mail
              </p>
              <input
                id="email"
                name="email"
                type="email"
                className="text-black block w-full rounded-md border border-gray-300 px-3 py-2 text-sm shadow-sm
                focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-orange-400"
                placeholder="cliente@exemplo.com"
              />
            </div>

            <button
              type="submit"
              className="mt-4 w-full rounded-md bg-orange-500 px-4 py-2 text-sm font-medium text-white shadow-sm
              hover:bg-orange-600 focus:outline-none focus:ring-2 focus:ring-orange-400 focus:ring-offset-1"
            >
              Cadastrar cliente
            </button>
          </form>
        </div>

        {/* --- LISTAGEM --- */}
        <div className="w-full max-w-md bg-white shadow-lg rounded-xl border border-orange-200 p-8">
          <h1 className="text-2xl text-gray-700 font-semibold text-center mb-6">
            Lista de Clientes
          </h1>

          {clientes.length === 0 ? (
            <p className="text-gray-600 text-center">Nenhum cliente cadastrado.</p>
          ) : (
            <div className="space-y-3">
              {clientes.map((item) => (

                <div
                  key={item.id}
                  className="relative border rounded-md p-3 shadow-sm bg-orange-50 text-gray-800"
                >
                  {/* Botão de deletar */}
                  <button
                    onClick={() => handleRemoveCliente(item.id)}
                    className="absolute top-2 right-2 text-red-600 hover:text-red-800"
                  >
                    <ClearIcon fontSize="medium" />
                  </button>
                  {/* Atualizar */}
                  <button
                    onClick={() => { setOpenModal(true); setDadosCliente(item); }}
                    className="absolute top-10 right-2 text-blue-600 hover:text-blue-800"
                  >
                    <SyncAltIcon fontSize="medium" />
                  </button>
                  <div className="flex flex-col">
                    <p className="py-0.5">
                      <span className="font-medium">Nome: </span>
                      {item.nome}
                    </p>
                    <p className="py-0.5">
                      <span className="font-medium">Documento: </span>
                      {item.cpf}
                    </p>
                    <p className="py-0.5">
                      <span className="font-medium">Telefone: </span>
                      {item.telefone}
                    </p>
                    <p className="py-0.5">
                      <span className="font-medium">Email: </span>
                      {item.email}
                    </p>
                  </div>

                </div>
              ))}
            </div>
          )}
        </div>
      </div>
      <ModalClienteUpdate
        open={openModal}
        onClose={() => setOpenModal(false)}
        dados={dadosCliente}
        setClientes={setClientes}
      />
    </>
  );
}